wire stack_destination_link=mem_instruction[11:7]==5'd1 || mem_instruction[11:7]==5'd5;
wire stack_source_link=mem_instruction[19:15]==5'd1 || mem_instruction[19:15]==5'd5;
wire stack_jal=mem_instruction[6:0]==7'h6f;
wire stack_jalr=mem_instruction[6:0]==7'h67 && mem_instruction[14:12]==0;
wire stack_return_hint=stack_jalr && stack_source_link &&
    (!stack_destination_link || mem_instruction[11:7]!=mem_instruction[19:15]);
wire stack_call_hint=(stack_jal || stack_jalr) && stack_destination_link;
wire stack_commit=mem_fire && !mem_fault && mem_branch;
rv32_btb #(.INDEX_BITS(BTB_INDEX_BITS),.ADDRESS_BITS(BTB_ADDRESS_BITS),.RETURN_STACK_DEPTH(2)) predictor (

reg conditional [0:ENTRIES-1];
reg return_entry [0:ENTRIES-1];
wire stack_available;
wire [31:0] stack_target;

generate if (RETURN_STACK_DEPTH>0) begin: return_stack
    localparam integer COUNT_BITS=$clog2(RETURN_STACK_DEPTH+1);
    localparam [COUNT_BITS-1:0] CAPACITY=COUNT_BITS'(RETURN_STACK_DEPTH);
    reg [COUNT_BITS-1:0] count;
    reg [31:0] addresses [0:RETURN_STACK_DEPTH-1];
    integer stack_index;
    assign stack_available=count!=0;
    assign stack_target=addresses[0];
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            count<=0;
        end else if (invalidate) begin
            count<=0;
        end else if (stack_push) begin
            addresses[0]<=update_pc+32'd4;
            if (!stack_pop || count==0) begin
                if (count<CAPACITY) count<=count+1'b1;
                for (stack_index=1;stack_index<RETURN_STACK_DEPTH;stack_index=stack_index+1)
                    addresses[stack_index]<=addresses[stack_index-1];
            end
        end else if (stack_pop && count!=0) begin
            count<=count-1'b1;
            for (stack_index=0;stack_index<RETURN_STACK_DEPTH-1;stack_index=stack_index+1)
                addresses[stack_index]<=addresses[stack_index+1];
        end
    end
end else begin: no_return_stack
    assign stack_available=1'b0;
    assign stack_target=32'd0;
end endgenerate
